using System.Text.Json;
using System.Diagnostics;
using DiceGame.Core;
using DiceGame.App;

namespace DiceGame.SkillTests;
internal static class Program
{
    static readonly string Root=AppContext.BaseDirectory;
    static readonly GameData Data=GameData.FromDirectory(Path.Combine(Root,"Data"));
    static readonly GameData Legacy=GameData.FromDirectory(Path.Combine(Root,"LegacyBalanceData"));
    static readonly CampaignCatalog Catalog=new(Data,File.ReadAllText(Path.Combine(Root,"Data/campaign.json")));
    static readonly List<object> Results=[];
    static int Passed,Failed;
    static int Main()
    {
        Test("configuration: 16 slots / four columns / exactly six types",()=>{Eq(Data.Game.Board.Slots,16);Eq(Data.Game.Board.Columns,4);Eq(Data.Game.Rules.MinDeck,6);Eq(Data.Game.Rules.MaxDeck,6);Near(Data.Game.Rules.DamageScale,.5);});
        Test("deck: 0–5 entries and duplicate six are all rejected",()=>{for(int i=0;i<6;i++){Check(!Data.ValidDeck(Data.DefaultDeck.Take(i)));Throws(()=>new Simulation(Data,Data.DefaultDeck.Take(i)));}Check(!Data.ValidDeck(Enumerable.Repeat("pulse",6)));Check(Data.ValidDeck(Data.DefaultDeck));});
        Test("deck: future seventh registered type is selectable, not automatically carried",()=>{var dice=Data.Dice.Select(CampaignCatalog.Copy).ToList();var next=CampaignCatalog.Copy(dice[0]);next.Id="future";dice.Add(next);var skills=Data.Skills.Values.Select(CampaignCatalog.Copy).ToList();var set=CampaignCatalog.Copy(skills[0]);set.Type="future";skills.Add(set);var data=new GameData(Encode(Data.Game),Encode(dice),Encode(Data.Upgrades),Encode(skills));Check(data.ValidDeck(data.DefaultDeck.Take(5).Append("future")));Check(!data.ValidDeck(data.Dice.Select(d=>d.Id)));Eq(new Simulation(data).State.Deck.Count,6);});
        Test("deck: locked die still blocks a complete six-die launch",()=>{var p=new CampaignProgression(Catalog);var state=p.NewState();state.UnlockedDice.Remove("bank");Throws(()=>p.PrepareRun(state,"region_01",Data.DefaultDeck,10));Eq(state.NextRunSerial,1L);});
        Test("deck UI backend: cannot save or start five-type draft",()=>{var a=App();a.Action("editDeck");a.Action("deck:bank");Eq(a.EditingDeck.Count,5);Check(!a.SaveDeck());Eq(a.Deck.Count,6);});
        Test("economy: six distinct opening dice create early growth headroom",()=>{var old=new Simulation(Legacy,Data.DefaultDeck,5);var now=Sim();Eq(now.Count,6);Check(now.State.Board.Take(6).Select(d=>d!.Type).SequenceEqual(Data.DefaultDeck));double oldDps=old.State.Board.Where(d=>d!=null).Sum(d=>old.Stats(d!).Volley/old.Stats(d!).Reload),nowDps=now.State.Board.Where(d=>d!=null).Sum(d=>now.Stats(d!).Volley/now.Stats(d!).Reload);Check(nowDps/oldDps>.80&&nowDps/oldDps<.86);Near(now.SummonCost,10);});
        Test("damage budget: sixteen-slot board retains original full-board capacity",()=>{var old=new Simulation(Legacy,Data.DefaultDeck,1);var now=Sim();foreach(string type in Data.DefaultDeck)for(int p=1;p<=6;p++){var d=new DieState{Type=type,Pips=p};Near(now.Stats(d).Volley*16,old.Stats(d).Volley*8);}});
        Test("summoning: 16th slot reachable, 17th rejected without cost and price scales with crowding",()=>{var s=Sim();s.State.Energy=10000;Near(s.SummonCost,10);while(s.Count<8)Check(s.Summon().Ok);Near(s.SummonCost,12);while(s.Count<16)Check(s.Summon().Ok);double energy=s.State.Energy;Check(!s.Summon().Ok);Eq(s.State.Energy,energy);Check(s.State.Board[15]!=null);});
        Test("input: fourth row accepts summon and move",()=>{var a=App();a.StartExpedition();a.Sim!.State.Energy=1000;var p=Data.SlotPosition(15);a.OnDown(p.X,p.Y);a.OnUp(p.X,p.Y);Check(a.Sim.State.Board[15]!=null);var q=Data.SlotPosition(14);a.Sim.State.Board[14]=null;a.OnDown(p.X,p.Y);a.OnMove(q.X,q.Y);a.OnUp(q.X,q.Y);Check(a.Sim.State.Board[14]!=null&&a.Sim.State.Board[15]==null);});
