        Test("instance scope: one die's branch does not upgrade another die",()=>{var s=Sim();MergeTo(s,3,"pulse");var other=s.MakeDie("pulse",3);other.Tier3="B";s.State.Board[2]=other;var before=s.Stats(other);Choose(s,"A");Near(s.Stats(other).Volley,before.Volley);Eq(other.Tier3,"B");});
