        Test("catalog: all registered branches and starter pairings produce finite bounded stats",()=>{var s=Sim();Eq(Data.Skills.Values.Sum(x=>x.Level3.Length+x.Level6.Length),Data.Dice.Length*4);foreach(var type in Data.DefaultDeck)foreach(string a in new[]{"A","B"})foreach(string b in new[]{"C","D"}){var q=s.Stats(Die(type,6,a,b));Check(double.IsFinite(q.Volley)&&q.Volley>0&&q.Reload>0&&q.Count<=18);Near(q.Damage*q.Count,q.Volley);Check(q.MaxBoost<=6&&q.Bounces<=36&&q.ChildCount<=10);}});
