        Test("save validation: wrong result ID/type/tier is rejected",()=>{var s=Sim();MergeTo(s,6,"pulse");var x=s.ExportSave();x.PendingSkills[0].DieId=999999;Throws(()=>Simulation.Restore(Data,x));x=s.ExportSave();x.PendingSkills[0].DiceType="blast";Throws(()=>Simulation.Restore(Data,x));x=s.ExportSave();x.PendingSkills[0].Tier=4;Throws(()=>Simulation.Restore(Data,x));});
        Test("save validation: missing branch or duplicate identity is rejected",()=>{var s=Sim();MergeTo(s,3,"pulse");Choose(s,"A");var x=s.ExportSave();x.Board[1]!.Tier3="";Throws(()=>Simulation.Restore(Data,x));x=s.ExportSave();x.Board[2]=x.Board[1]!.Copy();Throws(()=>Simulation.Restore(Data,x));});
