        Test("authoring: unknown modifier, missing branch and NaN fail validation",()=>{var text=File.ReadAllText(Path.Combine(Root,"Data/dice_skills.json"));Throws(()=>DiceSkillCatalog.Parse(text.Replace("damageMultiplier","damageMultipler")));var sets=Data.Skills.Values.Select(CampaignCatalog.Copy).ToArray();sets[0].Level3=[sets[0].Level3[0]];Throws(()=>DiceSkillCatalog.Parse(Encode(sets)));Throws(()=>new DiceSkillModifiers{DamageMultiplier=double.NaN}.Validate());});
