        Test("new format: corrupt five-die deck is rejected rather than silently filled",()=>{var a=App();a.StartExpedition();var env=new SaveEnvelope{Version=SaveCodec.CurrentVersion,Deck=Data.DefaultDeck.Take(5).ToList(),Run=a.Sim!.ExportSave(),Campaign=a.Campaign};Throws(()=>SaveCodec.Decode(Data,SaveCodec.Encode(env)));});
        Test("migration: terminal high-pip dice resolve missing skills when continued as endless",()=>
        {var s=Sim();s.State.Expedition=new ExpeditionState{Region=CampaignCatalog.Copy(Catalog.Regions["region_01"]),Outcome="victory",CanContinueEndless=true};s.State.Over=true;s.State.Board[0]!.Pips=6;var next=CampaignCatalog.Copy(s.State.Expedition);next.Endless=true;next.Outcome="";s.ContinueAsEndless(next);Eq(s.State.PendingSkills.Count,2);Choose(s,"B");Choose(s,"D");Eq(s.State.PendingShots.Count,0);Eq(s.State.Board[0]!.Tier3,"B");Eq(s.State.Board[0]!.Tier6,"D");});
        Test("headless stress: 16 six-pip skilled dice stay within object budgets",Stress);
        Directory.CreateDirectory("Artifacts");File.WriteAllText("Artifacts/skills-test-results.json",JsonSerializer.Serialize(new{passed=Passed,failed=Failed,tests=Results},new JsonSerializerOptions{WriteIndented=true}));
        Console.WriteLine($"\n{Passed} skill/board tests passed, {Failed} failed.");return Failed==0?0:1;
    }
    static void Stress()
    {
        var s=Empty();s.State.Health=12;for(int i=0;i<16;i++){var d=s.MakeDie(Data.DefaultDeck[i%6],6);d.Tier3=i%2==0?"A":"B";d.Tier6=i%3==0?"C":"D";s.State.Board[i]=d;}
        for(int i=0;i<56;i++){var e=Enemy(s,55+(i%7)*50,170+(i/7)*30);e.Hp=e.MaxHp=1e12;e.Speed=0;e.W=e.H=24;}
        s.Grid.Rebuild(s.State.Enemies);var watch=Stopwatch.StartNew();int maxP=0,maxQ=0;
        for(int i=0;i<1200;i++)
        {if(i%12==0)s.Fire(-1.5707963+Math.Sin(i*.03)*.6);s.Step(1d/120);maxP=Math.Max(maxP,s.State.Projectiles.Count);maxQ=Math.Max(maxQ,s.State.PendingShots.Count);Check(s.State.Projectiles.Count<=Data.Game.Rules.MaxProjectiles&&s.State.PendingShots.Count<=Data.Game.Rules.MaxQueuedShots);}
        watch.Stop();SaveCodec.ValidateRun(Data,s.ExportSave());Console.WriteLine($"STRESS: 1200 fixed steps / {watch.Elapsed.TotalMilliseconds:0} ms / max projectiles {maxP}, queued {maxQ}");
        File.WriteAllText("Artifacts/skills-stress.json",Encode(new{steps=1200,simulated_seconds=10,wall_milliseconds=watch.Elapsed.TotalMilliseconds,max_projectiles=maxP,max_pending=maxQ,scope="C# simulation only; no GPU/frame-rate claim"}));
    }
    static Simulation Sim()=>new(Data,Data.DefaultDeck,914);
    static Simulation Empty(){var s=Sim();s.State.Enemies.Clear();s.State.Projectiles.Clear();s.State.PendingShots.Clear();s.Events.Clear();return s;}
    static DieState Die(string type,int pips,string a="",string b="")=>new(){Id=10000,Type=type,Pips=pips,Tier3=a,Tier6=b};
    static EnemyState Enemy(Simulation s,double x,double y,string kind="normal")=>s.AddEnemy(new EnemyState{X=x,Y=y,W=20,H=20,Hp=1e6,Speed=0,Kind=kind,Wave=1});
    static ProjectileState Projectile(Simulation s,DieState d,double x=100,double y=300)=>s.MakeProjectile(x,y,-Math.PI/2,new ShotSnapshot{Type=d.Type,Pips=d.Pips,Stats=s.Stats(d)});
    static void Pair(Simulation s,int pips,bool clearShots=true)
    {Array.Clear(s.State.Board);s.State.Board[0]=s.MakeDie("pulse",pips);s.State.Board[1]=s.MakeDie("pulse",pips);if(pips>=3){s.State.Board[0]!.Tier3="A";s.State.Board[1]!.Tier3="B";}if(clearShots)s.State.PendingShots.Clear();s.State.PendingSkills.Clear();}
    static void NextType(Simulation s,string type)
    {var rng=new SeededRandom(s.Random.State);for(int i=0;i<1000;i++){uint before=rng.State;if(rng.Pick(s.State.Deck)==type){s.Random.State=before;return;}}throw new Exception("Cannot set test roll.");}
    static void MergeTo(Simulation s,int result,string type){Pair(s,result-1);NextType(s,type);Check(s.Merge(0,1).Ok);Eq(s.State.Board[1]!.Type,type);}
    static void Choose(Simulation s,string key){Check(s.ChooseDiceSkill(s.CurrentSkillChoice!.ChoiceId,key));}
    static GameApp App(Store? store=null)=>new(Data,store??new Store(),new Silent(),Catalog){NativeUi=true};
    static Store OldSave()
    {var catalog=new CampaignCatalog(Legacy,File.ReadAllText(Path.Combine(Root,"LegacyBalanceData/campaign.json")));var store=new Store();var a=new GameApp(Legacy,store,new Silent(),catalog);a.StartExpedition(9);a.Sim!.State.Board[0]!.Pips=6;a.Sim.State.Board[1]!.Pips=3;a.Save();return store;}
    static void Test(string name,Action body){try{body();Passed++;Results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){Failed++;Results.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+"\n"+ex);}}
    static void Check(bool value){if(!value)throw new Exception("assertion failed");}
    static void Eq<T>(T got,T want){if(!EqualityComparer<T>.Default.Equals(got,want))throw new Exception($"Expected {want}, got {got}");}
    static void Near(double got,double want){if(Math.Abs(got-want)>1e-7*Math.Max(1,Math.Abs(want)))throw new Exception($"Expected {want:R}, got {got:R}");}
    static void Throws(Action body){try{body();}catch{return;}throw new Exception("Expected rejection");}
    static string Encode<T>(T value)=>JsonSerializer.Serialize(value,GameData.JsonOptions);
    sealed class Store:IDesktopStorage{public string? Value;public bool Fail;public string? Read()=>Value;public uint NewSeed()=>914;public void Write(string s){if(Fail)throw new IOException("injected");Value=s;}}
    sealed class Silent:ISoundOutput{public bool Enabled{get;set;}public bool Music{get;set;}public void Unlock(){}public void Play(string kind,int variant=0){}public void Tick(double dt,bool active){}public void Suspend(){}}
}
